// Force terser to not use worker parallelization (avoids deadlocks),
// otherwise ./gradlew :composeApp:jsBrowserProductionWebpack takes 30 minutes
// to execute on Github and 10+ minutes on Mac
// NOTE: generated by ChatGPT
config.optimization = config.optimization || {};
config.optimization.minimizer = config.optimization.minimizer || [];

for (const minimizer of config.optimization.minimizer) {
  // Works across many terser-webpack-plugin versions
  if (minimizer?.constructor?.name === "TerserPlugin") {
    minimizer.options = minimizer.options || {};
    minimizer.options.parallel = false; // or 1
  }
}
